const lead = $json;

const scraperApiKey =
  $env.SCRAPERAPI_KEY ||
  $env.SCRAPER_API_KEY;

const facebookUrl =
  String(
    lead.facebook_url || ''
  ).trim();

const instagramUrl =
  String(
    lead.instagram_url || ''
  ).trim();

let scraperCalls = 0;
const scrapeErrors = [];

const scrapeProfile = async (
  platform,
  targetUrl
) => {
  if (!targetUrl) {
    return '';
  }

  if (!scraperApiKey) {
    scrapeErrors.push(
      `Missing ScraperAPI key for ${platform}`
    );

    return '';
  }

  scraperCalls++;

  try {
    const response =
      await this.helpers.httpRequest({
        method: 'GET',

        url:
          'https://api.scraperapi.com/' +
          '?api_key=' +
          encodeURIComponent(
            scraperApiKey
          ) +
          '&render=false' +
          '&url=' +
          encodeURIComponent(
            targetUrl
          ),

        timeout: 25000,
      });

    let html = '';

    if (
      typeof response === 'string'
    ) {
      html = response;
    } else if (
      typeof response?.body ===
      'string'
    ) {
      html = response.body;
    } else if (
      typeof response?.data ===
      'string'
    ) {
      html = response.data;
    }

    // Avoid excessive execution memory
    return html.slice(0, 150000);
  } catch (error) {
    scrapeErrors.push(
      `${platform}: ${
        error.message ||
        'scrape failed'
      }`
    );

    return '';
  }
};

// Only existing social profiles consume credits
const [
  facebookHtml,
  instagramHtml,
] = await Promise.all([
  scrapeProfile(
    'facebook',
    facebookUrl
  ),

  scrapeProfile(
    'instagram',
    instagramUrl
  ),
]);

return [{
  json: {
    ...lead,

    fb_html:
      facebookHtml,

    ig_html:
      instagramHtml,

    social_scraper_calls:
      scraperCalls,

    social_scrape_errors:
      scrapeErrors,
  },
}];

const lead = $json;
const cfg = $('config').first().json;

const apiKey = $env.OPENAI_API_KEY;
const agencyName =
  cfg.agencyName || 'Atrium Solution';

const calendarLink =
  cfg.calendarLink ||
  'https://calendly.com/atrium-solution';

const model =
  cfg.openaiModel || 'gpt-4o-mini';

const mobileScore =
  lead.pagespeed_mobile ??
  lead.pagespeed_score ??
  null;

const desktopScore =
  lead.pagespeed_desktop ??
  null;

const seoScore =
  lead.seo_score ??
  null;

const parseJsonField = (value, fallback) => {
  if (value == null || value === '') {
    return fallback;
  }

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (_error) {
      return fallback;
    }
  }

  return value;
};

const performanceJson =
  parseJsonField(lead.performance_json, {});

const accessibilityScore =
  performanceJson?.mobile
    ?.accessibility_score ??
  null;

// Normalize WF2 pain points
const normalizePainPoint = (
  painPoint,
  index
) => {
  if (typeof painPoint === 'string') {
    return {
      area: 'website',
      problem: painPoint,
      solution:
        'Review and resolve this website issue',
      severity: 'medium',
    };
  }

  return {
    area:
      painPoint?.area ||
      painPoint?.platform ||
      'website',

    problem:
      painPoint?.problem ||
      `Website issue ${index + 1}`,

    solution:
      painPoint?.solution ||
      'Review and resolve this issue',

    severity:
      painPoint?.severity ||
      'medium',
  };
};

const rawPainPoints =
  parseJsonField(
    lead.enrichment_pain_points,
    []
  );

const storedPainPoints =
  Array.isArray(rawPainPoints)
    ? rawPainPoints
    : [];

const websitePainPoints =
  storedPainPoints.map(normalizePainPoint);

// Prevent duplicate metric observations
const hasProblemContaining = (text) =>
  websitePainPoints.some((point) =>
    String(point.problem || '')
      .toLowerCase()
      .includes(text.toLowerCase())
  );

if (
  mobileScore !== null &&
  mobileScore < 60 &&
  !hasProblemContaining('mobile pagespeed')
) {
  websitePainPoints.push({
    area: 'performance',
    problem:
      `Mobile PageSpeed score is ${mobileScore}/100`,
    solution:
      'Improve Core Web Vitals, images, caching, and mobile loading speed',
    severity:
      mobileScore < 40
        ? 'high'
        : 'medium',
  });
}

if (
  desktopScore !== null &&
  desktopScore < 70 &&
  !hasProblemContaining('desktop pagespeed')
) {
  websitePainPoints.push({
    area: 'performance',
    problem:
      `Desktop PageSpeed score is ${desktopScore}/100`,
    solution:
      'Optimize desktop assets, caching, and server response time',
    severity:
      desktopScore < 50
        ? 'high'
        : 'medium',
  });
}

if (
  seoScore !== null &&
  seoScore < 70 &&
  !hasProblemContaining('seo score')
) {
  websitePainPoints.push({
    area: 'seo',
    problem:
      `SEO score is ${seoScore}/100`,
    solution:
      'Improve metadata, page structure, and on-page SEO',
    severity:
      seoScore < 50
        ? 'high'
        : 'medium',
  });
}

if (
  accessibilityScore !== null &&
  accessibilityScore < 70 &&
  !hasProblemContaining(
    'accessibility score'
  )
) {
  websitePainPoints.push({
    area: 'accessibility',
    problem:
      `Accessibility score is ${accessibilityScore}/100`,
    solution:
      'Improve contrast, labels, navigation, and accessible interactions',
    severity:
      accessibilityScore < 50
        ? 'high'
        : 'medium',
  });
}

// Social audit only when a profile exists
const socialPainPoints = [];

const facebookHtml =
  String(lead.fb_html || '')
    .toLowerCase();

const instagramHtml =
  String(lead.ig_html || '')
    .toLowerCase();

const hasFacebook =
  Boolean(
    String(
      lead.facebook_url || ''
    ).trim()
  );

const hasInstagram =
  Boolean(
    String(
      lead.instagram_url || ''
    ).trim()
  );

// Only record explicit evidence.
// Login walls or empty scraper responses
// are not treated as business problems.
if (
  hasFacebook &&
  facebookHtml.length > 500 &&
  (
    facebookHtml.includes(
      'page isn\'t available'
    ) ||
    facebookHtml.includes(
      'content isn\'t available'
    )
  )
) {
  socialPainPoints.push({
    platform: 'facebook',
    problem:
      'Linked Facebook page appears unavailable to public visitors',
    solution:
      'Review the Facebook page visibility and public business settings',
    severity: 'medium',
  });
}

if (
  hasInstagram &&
  instagramHtml.length > 500 &&
  (
    instagramHtml.includes(
      'this account is private'
    ) ||
    instagramHtml.includes(
      'page isn\'t available'
    )
  )
) {
  socialPainPoints.push({
    platform: 'instagram',
    problem:
      'Linked Instagram profile appears private or unavailable',
    solution:
      'Review profile visibility and business-account settings',
    severity: 'medium',
  });
}

// Use only evidence-based findings
const allPainPoints = [
  ...websitePainPoints,
  ...socialPainPoints,
]
  .filter(
    (point) =>
      point.problem &&
      point.solution
  )
  .slice(0, 8);

const auditSummary =
  allPainPoints
    .map(
      (point, index) =>
        `${index + 1}. ` +
        `[${String(
          point.area ||
          point.platform ||
          'website'
        ).toUpperCase()} | ` +
        `${String(
          point.severity ||
          'medium'
        ).toUpperCase()}] ` +
        `${point.problem}\n` +
        `Recommended fix: ` +
        `${point.solution}`
    )
    .join('\n');

let auditSuccess = false;
let emailSubject = null;
let emailBody = null;
let failureReason = null;

if (!apiKey) {
  failureReason =
    'Missing OPENAI_API_KEY';
} else if (!allPainPoints.length) {
  failureReason =
    'No evidence-based audit findings available';
} else {
  const systemPrompt = `
You are a senior digital marketing consultant for ${agencyName}.

Write a concise, personalized cold outreach email using only the audit evidence supplied by the user.

Rules:
- Do not invent facts, metrics, or problems.
- Mention 2 or 3 specific audit findings.
- Tone must be professional, helpful, and consultative.
- Do not sound aggressive or overly sales-focused.
- Subject must be under 60 characters.
- Body must be under 250 words.
- Structure: short introduction, findings, how we can help, soft CTA.
- Include this CTA exactly:
  Book a free 15-minute strategy call: ${calendarLink}
- Sign off:
  The ${agencyName} Team

Return valid JSON only:
{
  "subject": "email subject",
  "body": "complete plain-text email"
}
`.trim();

  const userPrompt = `
Business name: ${lead.business_name}
Industry: ${lead.category || 'Not available'}
Location: ${lead.city || ''}${
    lead.state
      ? ', ' + lead.state
      : ''
  }
Website: ${lead.website_url || ''}
Google rating: ${
    lead.rating
      ? `${lead.rating}/5 (${lead.review_count || 0} reviews)`
      : 'Not available'
  }

Audit findings:
${auditSummary}
`.trim();

  const http =
    this.helpers.httpRequest;

  let lastError =
    'Unknown OpenAI error';

  for (
    let attempt = 1;
    attempt <= 2;
    attempt++
  ) {
    try {
      const response = await http({
        method: 'POST',
        url:
          'https://api.openai.com/v1/chat/completions',

        headers: {
          Authorization:
            `Bearer ${apiKey}`,

          'Content-Type':
            'application/json',
        },

        body: {
          model,

          messages: [
            {
              role: 'system',
              content: systemPrompt,
            },
            {
              role: 'user',
              content: userPrompt,
            },
          ],

          response_format: {
            type: 'json_object',
          },

          temperature: 0.4,
          max_tokens: 650,
        },

        json: true,
        timeout: 60000,
      });

      const content =
        String(
          response?.choices?.[0]
            ?.message?.content || ''
        ).trim();

      if (!content) {
        throw new Error(
          'OpenAI returned empty content'
        );
      }

      const parsed =
        JSON.parse(content);

      const subject =
        String(
          parsed.subject || ''
        ).trim();

      const body =
        String(
          parsed.body || ''
        ).trim();

      const wordCount =
        body
          .split(/\s+/)
          .filter(Boolean)
          .length;

      if (!subject) {
        throw new Error(
          'AI response missing subject'
        );
      }

      if (
        body.length < 50 ||
        wordCount > 300
      ) {
        throw new Error(
          'AI email body failed validation'
        );
      }

      emailSubject =
        subject.slice(0, 100);

      emailBody = body;
      auditSuccess = true;
      lastError = null;

      break;
    } catch (error) {
      lastError =
        error.message ||
        'OpenAI request failed';

      if (attempt < 2) {
        await new Promise(
          (resolve) =>
            setTimeout(resolve, 2000)
        );
      }
    }
  }

  if (!auditSuccess) {
    failureReason = lastError;
  }
}

return [{
  json: {
    id: lead.id,
    business_name:
      lead.business_name,
    email: lead.email,
    website_url:
      lead.website_url,
    city: lead.city,
    state: lead.state,
    category: lead.category,
    rating: lead.rating,
    review_count:
      lead.review_count,
    campaign_id:
      lead.campaign_id,
    retry_count:
      lead.retry_count || 0,

    pagespeed_mobile:
      mobileScore,
    pagespeed_desktop:
      desktopScore,
    seo_score:
      seoScore,

    website_pain_points:
      websitePainPoints,
    social_pain_points:
      socialPainPoints,

    audit_summary:
      auditSummary,

    pain_points_count:
      allPainPoints.length,

    audit_success:
      auditSuccess,

    email_subject:
      emailSubject,

    email_body:
      emailBody,

    failure_reason:
      failureReason,
  },
}];

const cfg =
  $('config').first().json;

const safeAll = (nodeName) => {
  try {
    return $(nodeName).all();
  } catch (_error) {
    return [];
  }
};

const successfulDrafts =
  safeAll(
    'Postgres — Save Draft & pending_review'
  );

const failedAttempts =
  safeAll(
    'Postgres — Update audit_failed'
  );

const terminalFailures =
  failedAttempts.filter(
    (item) =>
      item.json.status ===
      'audit_failed'
  );

const retryQueued =
  failedAttempts.filter(
    (item) =>
      item.json.status ===
      'enriched'
  );

const successfulLeadIds =
  successfulDrafts
    .map(
      (item) =>
        item.json.lead_id
    )
    .filter(Boolean);

const failedLeadIds =
  failedAttempts
    .map(
      (item) =>
        item.json.id
    )
    .filter(Boolean);

const startedAt =
  new Date(
    cfg.runStartTs
  ).getTime();

const durationMs =
  Number.isFinite(startedAt)
    ? Date.now() - startedAt
    : 0;

return [{
  json: {
    workflow_name:
      cfg.workflowName ||
      'audit_and_draft',

    leads_processed:
      successfulDrafts.length,

    leads_failed:
      failedAttempts.length,

    terminal_failed:
      terminalFailures.length,

    retry_queued:
      retryQueued.length,

    duration_ms:
      durationMs,

    notes:
      'WF3 audit_and_draft' +
      ' | pending_review=' +
      successfulDrafts.length +
      ' | retry_queued=' +
      retryQueued.length +
      ' | audit_failed=' +
      terminalFailures.length +
      ' | success_ids=' +
      (
        successfulLeadIds.join(',') ||
        'none'
      ) +
      ' | failed_ids=' +
      (
        failedLeadIds.join(',') ||
        'none'
      ),
  },
}];
